#!/usr/bin/env python3
"""Render every generated file of the repository from results/cells.tsv.

    python3 results/render.py           write the outputs
    python3 results/render.py --check   exit 1 if any output is out of date

results/cells.tsv is the only place the numbers are typed. This script checks
it (bits per CN against the byte counts, SHA-256 syntax, unique tags) and
writes:

    README.md                  the comparison table and the hosted-file table,
                               between <!-- table:start/end --> and
                               <!-- files:start/end --> markers
    cells/<dir>/CELL           one key = value manifest per cell
    oracle/ORACLE, oracle/TEXT manifests of the oracle and of the text table
    results/INTERMEDIATES      sizes and hashes of the shared intermediates
    SHA256SUMS                 the hosted files (sha256sum -c format), byte for byte
                               the SHA256SUMS of the data directory's v1/ folder
    results/comparison.tex     the two-page comparison (make pdf -> COMPARISON.pdf)

Python 3.8 or later, standard library only.
"""

import argparse
import csv
import re
import sys
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
TSV = ROOT / "results" / "cells.tsv"
GEN = "generated by results/render.py from results/cells.tsv; do not edit"
HEX = set("0123456789abcdef")
CELL_ORDER = ["000", "001", "100", "101", "010", "011", "110", "111", "111x"]
GOLDEN = {"000": "c000.vbg", "001": "c001.cnd.gz", "100": "c100.vbg", "101": "c101.cnd1",
          "010": "c010.pwt2n", "011": "c011.pwt2", "110": "c110.pwt2n", "111": "c111.pwt2",
          "111x": "c111x.pwt2"}


class RenderError(Exception):
    pass


# ------------------------------------------------------------------ input

def read_rows():
    lines = [ln for ln in TSV.read_text(encoding="utf-8").splitlines()
             if ln.strip() and not ln.startswith("#")]
    rows = list(csv.reader(lines, delimiter="\t", quoting=csv.QUOTE_NONE))
    head = rows[0]
    out = []
    for r in rows[1:]:
        if len(r) != len(head):
            raise RenderError("row %r has %d fields, header has %d" % (r[0], len(r), len(head)))
        out.append(dict(zip(head, r)))
    return out


def is_sha(s):
    return len(s) == 64 and set(s) <= HEX


def q(x, places):
    return x.quantize(Decimal(1).scaleb(-places), rounding=ROUND_HALF_UP)


def validate(rows):
    tags = set()
    facts = {}
    for r in rows:
        if r["tag"] in tags:
            raise RenderError("tag %s appears twice" % r["tag"])
        tags.add(r["tag"])
        if r["kind"] == "fact":
            facts[r["tag"]] = r["value"]
    N = Decimal(facts["count"])
    text = None
    for r in rows:
        if r["kind"] == "fact":
            continue
        if r["sha256"] != "-" and not is_sha(r["sha256"]):
            raise RenderError("%s: sha256 %r is not a SHA-256" % (r["tag"], r["sha256"]))
        if r["values_sha256"] != "-" and not is_sha(r["values_sha256"]):
            raise RenderError("%s: values_sha256 is not a SHA-256" % r["tag"])
        b = r["bytes"]
        if b == "-":
            continue
        if not b.isdigit():
            raise RenderError("%s: bytes %r" % (r["tag"], b))
        bits = Decimal(int(b)) * 8 / N
        for col, places in (("bits_per_cn", 3), ("bits_printed", 2)):
            if r[col] != "-" and r[col] != str(q(bits, places)):
                raise RenderError("%s: %s %s, but %s bytes give %s" % (r["tag"], col, r[col], b, q(bits, places)))
        if r["tag"] == "text":
            text = int(b)
        if r["kind"] in ("cell", "reference", "checkpoint") and r["file"] != "-":
            if r["hosted"] == "yes":
                if not (r["url"].startswith("https://") and r["url"].endswith("/" + r["file"])):
                    raise RenderError("%s: hosted, but url %r does not end in /%s" % (r["tag"], r["url"], r["file"]))
            elif r["kind"] != "reference" and r["url"] != "not hosted":
                raise RenderError("%s: not hosted, but url is %r" % (r["tag"], r["url"]))
    for t in CELL_ORDER:
        if t not in tags:
            raise RenderError("cell %s missing" % t)
    return facts, N, text


# ------------------------------------------------------------------ formatting

def grp(n):
    return "{:,}".format(int(n))


def bits_exact(r, N):
    return str(q(Decimal(int(r["bytes"])) * 8 / N, 9))


def ratio(r, text):
    return str(q(Decimal(text) / Decimal(int(r["bytes"])), 2))


def md(s):
    """Markdown for a label: d_min, d*, r*, 10^k."""
    s = s.replace("d_min", "d<sub>min</sub>").replace("d*", "d\\*").replace("r*", "r\\*")
    for k in ("24", "12"):
        s = s.replace("10^" + k, "10<sup>%s</sup>" % k)
    return s


def tex(s):
    """LaTeX for a label, escaping the specials and setting d_min, d*, r*, 10^k."""
    toks = {"d_min": "@@DMIN@@", "d*": "@@DSTAR@@", "r*": "@@RSTAR@@", "10^24": "@@E24@@", "10^12": "@@E12@@"}
    for k, v in toks.items():
        s = s.replace(k, v)
    for a, b in (("\\", "\\textbackslash{}"), ("&", "\\&"), ("%", "\\%"), ("$", "\\$"), ("#", "\\#"),
                 ("_", "\\_"), ("{", "\\{"), ("}", "\\}"), ("~", "\\textasciitilde{}"), ("^", "\\^{}")):
        s = s.replace(a, b)
    back = {"@@DMIN@@": "$d_{\\min}$", "@@DSTAR@@": "$d^{\\ast}$", "@@RSTAR@@": "$r^{\\star}$",
            "@@E24@@": "$10^{24}$", "@@E12@@": "$10^{12}$"}
    for k, v in back.items():
        s = s.replace(k, v)
    return s


def dash(v):
    return "" if v in ("-", "") else v


def hosted_rows(rows):
    """The hosted files, in table order: the cells, then the oracle."""
    order = {t: i for i, t in enumerate(CELL_ORDER + ["oracle"])}
    hosted = [r for r in rows if r["kind"] in ("cell", "reference", "checkpoint") and r["hosted"] == "yes"]
    return sorted(hosted, key=lambda r: (order.get(r["tag"], 99), r["tag"]))


def data_folder(rows):
    """The folder that serves the hosted files (the common prefix of their urls)."""
    dirs = {r["url"].rsplit("/", 1)[0] + "/" for r in hosted_rows(rows)}
    if len(dirs) != 1:
        raise RenderError("the hosted files are not in one folder: %s" % sorted(dirs))
    return dirs.pop()


def threads_as_run(text):
    """'as run: extraction 15, search 6, encode 4' -> '15 threads for the extraction, 6 for the search and 4 for encoding'."""
    steps = re.findall(r"([a-z]+) (\d+)", text.replace("as run:", ""))
    if not steps:
        raise RenderError("cannot read build_threads %r" % text)
    names = {"extraction": "the extraction", "search": "the search", "encode": "encoding"}
    parts = ["%s for %s" % (n, names.get(s, s)) for s, n in steps]
    parts[0] = parts[0].replace(" for ", " threads for ", 1)
    return parts[0] if len(parts) == 1 else ", ".join(parts[:-1]) + " and " + parts[-1]


def threads_sentence(text):
    """'as run: extraction 15, search 6, encode 4' -> 'Extraction ran on 15 threads, the search on 6 and encoding on 4'."""
    steps = re.findall(r"([a-z]+) (\d+)", text.replace("as run:", ""))
    if not steps:
        raise RenderError("cannot read build_threads %r" % text)
    names = {"extraction": "extraction", "search": "the search", "encode": "encoding"}
    parts = ["%s on %s" % (names.get(s, s), n) for s, n in steps]
    parts[0] = parts[0].replace(" on ", " ran on ", 1) + " threads"
    s = parts[0] if len(parts) == 1 else ", ".join(parts[:-1]) + " and " + parts[-1]
    return s[0].upper() + s[1:]


def dstar_rebuild_min(facts):
    """Minutes of the d* rebuild from its own exported paths (export + re-encode), rounded."""
    return q((Decimal(facts["dstar_export_s"]) + Decimal(facts["dstar_reencode_s"])) / 60, 0)


def dstar_rebuild_parts(facts):
    """'Exporting the stored paths takes 5.1 min on one thread, and encoding them takes 7.5 min on 4 threads.'"""
    return ("Exporting the stored paths takes %s min on one thread, and encoding them takes %s min on 4 threads."
            % (q(Decimal(facts["dstar_export_s"]) / 60, 1), q(Decimal(facts["dstar_reencode_s"]) / 60, 1)))


CONDITIONS = {"otherwise idle machine": "on an otherwise idle machine", "other jobs running": "while other jobs ran"}


def when(field):
    """certify_date '2026-09-26 (otherwise idle machine)' -> 'on 2026-09-26 on an otherwise idle machine'."""
    m = re.match(r"^(\d{4}-\d{2}-\d{2}) \(([^)]*)\)$", field)
    if not m or m.group(2) not in CONDITIONS:
        raise RenderError("cannot read certify_date %r (known conditions: %s)" % (field, ", ".join(CONDITIONS)))
    return "on %s %s" % (m.group(1), CONDITIONS[m.group(2)])


# ------------------------------------------------------------------ manifests

def manifest(lines, title):
    out = ["# %s -- %s." % (title, GEN)]
    w = max(len(k) for k, _ in lines)
    for k, v in lines:
        out.append("%s = %s" % (k.ljust(w), v))
    return "\n".join(out) + "\n"


def cell_manifest(r, N, text, byt):
    sw = r["switches"]
    half = "C = %s half" % sw[2]
    lines = [
        ("tag", r["tag"]),
        ("switches", "A=%s B=%s C=%s (A: d_min instead of n; B: prime wavelet tree instead of a sorted list; C: coding tricks)" % tuple(sw)),
        ("meaning", r["label"]),
        ("table2_row", "%s row, %s (cell %s)" % (r["table_row"], half, sw)),
        ("hosted", r["hosted"]),
        ("file", r["file"]),
        ("format", r["format"]),
        ("spec", r["spec"]),
        ("bytes", r["bytes"]),
        ("bits_per_cn", bits_exact(r, N)),
        ("bits_per_cn_printed", r["bits_printed"]),
        ("x_smaller_than_text", ratio(r, text)),
        ("sha256", r["sha256"]),
        ("values_sha256", r["values_sha256"]),
        ("url", r["url"]),
        ("build_extract_s", r["build_extract_s"]),
        ("build_search_s", r["build_search_s"]),
        ("build_encode_s", r["build_encode_s"]),
        ("build_min", r["build_min"]),
        ("build_threads", r["build_threads"]),
        ("decode_s", r["decode_s"]),
        ("decode_cns_min", r["cns_only_min"]),
        ("decode_list_only_min", r["list_only_min"]),
        ("decode_cns_primes_min", r["cns_primes_min"]),
        ("certify_s", r["certify_s"]),
        ("certify_threads", r["certify_threads"]),
        ("certify_tool", r["certify_tool"]),
        ("certify_measured", r["certify_date"]),
        ("ram_gb", r["ram_gb"]),
        ("disk_gb", r["disk_gb"]),
        ("encoder_sha256", r["encoder_sha256"]),
        ("gate_sha256", r["gate_sha256"]),
        ("golden", "tests/prefix/golden_files/" + GOLDEN[r["tag"]]),
        ("build", "cells/%s/build.sh" % r["dir"]),
        ("decode", "cells/%s/decode.sh" % r["dir"]),
        ("notes", r["notes"]),
    ]
    if r["tag"] == "111x":
        m = byt["dstar_masks"]
        lines[-1:-1] = [("masks_file", m["file"]), ("masks_bytes", m["bytes"]),
                        ("masks_sha256", m["sha256"]), ("masks_hosted", m["hosted"]),
                        ("masks_notes", m["notes"])]
    return manifest(lines, "cells/%s/CELL" % r["dir"])


def oracle_manifests(byt, N):
    o, t = byt["oracle"], byt["text"]
    om = manifest([
        ("tag", "oracle"),
        ("meaning", o["label"]),
        ("hosted", o["hosted"]),
        ("file", o["file"]),
        ("format", o["format"]),
        ("spec", o["spec"]),
        ("bytes", o["bytes"]),
        ("bits_per_cn", bits_exact(o, N)),
        ("bits_per_cn_printed", o["bits_printed"]),
        ("sha256", o["sha256"]),
        ("text_sha256", o["values_sha256"]),
        ("url", o["url"]),
        ("build_s", o["build_encode_s"]),
        ("build_min", o["build_min"]),
        ("decode_s", o["decode_s"]),
        ("disk_gb", o["disk_gb"]),
        ("build", "oracle/build.sh"),
        ("decode", "oracle/decode.sh"),
        ("notes", o["notes"]),
    ], "oracle/ORACLE")
    tm = manifest([
        ("tag", "text"),
        ("meaning", t["label"]),
        ("hosted", "no (served by its authors)"),
        ("file", t["file"]),
        ("format", t["format"]),
        ("bytes", t["bytes"]),
        ("lines", str(N)),
        ("bits_per_cn", bits_exact(t, N)),
        ("sha256", t["sha256"]),
        ("url", t["url"]),
        ("notes", t["notes"]),
    ], "oracle/TEXT")
    return om, tm


def intermediates(rows):
    lines = []
    for r in rows:
        if r["kind"] != "intermediate":
            continue
        k = r["tag"]
        lines += [(k + ".file", r["file"]), (k + ".bytes", r["bytes"]), (k + ".sha256", r["sha256"]),
                  (k + ".what", r["label"]), (k + ".made_by", r["notes"])]
    return manifest(lines, "results/INTERMEDIATES")


def sha256sums(rows):
    return "".join("%s  %s\n" % (r["sha256"], r["file"]) for r in hosted_rows(rows))


# ------------------------------------------------------------------ README

def readme_table(rows, byt, facts, text):
    head = ("| Cell | Representation | Bytes | Bits per CN | Smaller than text | Build (min) "
            "| Decode, CNs (min) | CNs + primes (min) | Certify (s) | SHA-256 | Hosted |")
    out = [head, "|" + "---|" * 11]
    for t in CELL_ORDER:
        r = byt[t]
        dec = r["cns_only_min"] + (" [b]" if r["list_only_min"] != "-" else "")
        prim = r["cns_primes_min"] + (" [a]" if r["cns_primes_min"] != r["cns_only_min"] or r["list_only_min"] != "-" else "")
        bld = r["build_min"] + (" [c]" if t == "111x" else "")
        cert = r["certify_s"] + (" (%s threads)" % r["certify_threads"] if r["certify_threads"] not in ("1", "-") else "")
        out.append("| %s | %s | %s | %s | %s | %s | %s | %s | %s | `%s` | %s |" % (
            "111 with d\\*" if t == "111x" else t, md(r["label"]), grp(r["bytes"]), r["bits_printed"],
            ratio(r, text), bld, dec, prim, cert, r["sha256"][:8], r["hosted"]))
    o, tx, gz = byt["oracle"], byt["text"], byt["gzip"]
    out.append("| ref | %s | %s | %s | %s | about %s (from the text) | | | | `%s` | %s |" % (
        "oracle (binary copy of the table)", grp(o["bytes"]), o["bits_printed"], ratio(o, text), o["build_min"], o["sha256"][:8], o["hosted"]))
    out.append("| ref | %s | %s | %s | 1 | | | | | `%s` | by its authors |" % (
        "text table", grp(tx["bytes"]), tx["bits_printed"], tx["sha256"][:8]))
    for k in ("gzip", "zstd", "xz"):
        g = byt[k]
        out.append("| ref | %s | %s | %s | %s | | | | | | no |" % (md(g["label"]), grp(g["bytes"]), g["bits_printed"], ratio(g, text)))
    b100, b101 = byt["100"], byt["101"]
    d = byt["111x"]
    out += [
        "",
        "N = %s Carmichael numbers (CNs). Times are single-threaded minutes on an %s, except where noted." % (grp(facts["count"]), facts["machine"]),
        "",
        "- [a] The factoring part is scaled from the measured per-number cost on %s CNs (every 100th oracle block). "
        "Every factorization was also checked against the oracle." % grp(facts["factor_sample"]),
        "- [b] The d<sub>min</sub> list itself decodes in %s (100) and %s (101) minutes. The rest is factoring every d." % (b100["list_only_min"], b101["list_only_min"]),
        "- [c] As run, with %s. The search alone took %s s (%s h). The file stores the chosen divisors, "
        "so it can be rebuilt without repeating the search. That rebuild takes about %s min. %s" % (
            threads_as_run(d["build_threads"]), grp(Decimal(d["build_search_s"]).to_integral_value(ROUND_HALF_UP)),
            q(Decimal(d["build_search_s"]) / 3600, 1), dstar_rebuild_min(facts), dstar_rebuild_parts(facts)),
        "- Certify decodes the file and compares every CN with the oracle. The trees were certified %s. "
        "Cell 101 was certified %s. Cells 000, 001 and 100 were certified %s." % (
            when(byt["111"]["certify_date"]), when(b101["certify_date"]), when(byt["000"]["certify_date"])),
    ]
    return "\n".join(out)


def readme_files(rows, byt):
    out = ["| File | Cell | Bytes | SHA-256 |", "|---|---|---|---|"]
    total = 0
    for r in hosted_rows(rows):
        total += int(r["bytes"])
        cell = {"oracle": "oracle", "111x": "111 with d\\*"}.get(r["tag"], r["tag"])
        out.append("| [`%s`](%s) | %s | %s | `%s` |" % (r["file"], r["url"], cell, grp(r["bytes"]), r["sha256"]))
    out.append("| total | | %s | |" % grp(total))
    return "\n".join(out)


def splice(text, name, body):
    a, b = "<!-- %s:start -->" % name, "<!-- %s:end -->" % name
    i, j = text.find(a), text.find(b)
    if i < 0 or j < i:
        raise RenderError("README.md lacks the %s markers" % name)
    note = "<!-- %s -->" % GEN
    return text[:i + len(a)] + "\n" + note + "\n" + body + "\n" + text[j:]


# ------------------------------------------------------------------ LaTeX

TEX_HEAD = r"""%% results/comparison.tex -- @GEN@.
%% make pdf -> COMPARISON.pdf (two pages).
\documentclass[10pt]{article}
\usepackage[letterpaper,margin=0.75in]{geometry}
\usepackage[T1]{fontenc}
\usepackage{lmodern}
\usepackage{array,booktabs,colortbl,xcolor}
\usepackage[hidelinks]{hyperref}
\setlength{\parindent}{0pt}
\setlength{\parskip}{4pt}
\pagestyle{empty}
\newcommand{\sw}[1]{\textsf{#1}}
\newcommand{\dmin}{d_{\min}}
\begin{document}
"""


def best(vals):
    nums = [Decimal(v) for v in vals if v not in ("-", "")]
    return min(nums) if nums else None


def comparison_tex(rows, byt, facts, text, N):
    cells = [byt[t] for t in CELL_ORDER]
    minbits = min(Decimal(r["bits_printed"]) for r in cells)
    minbuild = best(r["build_min"] for r in cells)
    mindec = best(r["cns_only_min"] for r in cells)
    minprim = best(r["cns_primes_min"] for r in cells)

    def cellv(r):
        b = r["bits_printed"]
        bs = ("\\cellcolor{bitsdk}\\textbf{%s}" % b) if Decimal(b) == minbits else b
        bl = r["build_min"]
        bl = ("\\textbf{%s}" % bl) if Decimal(bl) == minbuild else bl
        if r["tag"] == "111x":
            bl += "\\rlap{$^\\S$}"
        dc = r["cns_only_min"]
        dc = ("\\textbf{%s}" % dc) if Decimal(dc) == mindec else dc
        if r["list_only_min"] != "-":
            dc += "\\rlap{$^\\dagger$}"
        pr = r["cns_primes_min"]
        pr = ("\\textbf{%s}" % pr) if Decimal(pr) == minprim else pr
        tag = "\\sw{%s}" % r["switches"] + ("$^\\ddagger$" if r["tag"] == "111x" else "")
        return [tag, bs, bl, dc, pr]

    lines = [TEX_HEAD.replace("@GEN@", GEN)]
    lines.append(r"""{\Large\bfseries The prime wavelet tree: comparison of the stored files}\\[2pt]
{\small All Carmichael numbers below $10^{24}$: $N$~=~%s (CNs). Every number on this page comes from \texttt{results/cells.tsv}.}

\begin{center}
{\renewcommand{\arraystretch}{1.3}\small
\setlength{\tabcolsep}{3pt}\setlength{\aboverulesep}{0pt}\setlength{\belowrulesep}{0pt}%%
\definecolor{bitsbg}{rgb}{0.80,0.88,0.97}\definecolor{bitsdk}{rgb}{0.55,0.71,0.91}%%
\definecolor{bldbg}{rgb}{0.86,0.95,0.84}\definecolor{decbg}{rgb}{1.00,0.96,0.85}%%
\newcommand{\two}[2]{{\renewcommand{\arraystretch}{1}\begin{tabular}[c]{@{}c@{}}\textbf{#1}\\\textbf{#2}\end{tabular}}}%%
\begin{tabular}{l|c>{\columncolor{bitsbg}}r>{\columncolor{bldbg}}r>{\columncolor{decbg}}r>{\columncolor{decbg}}r|c>{\columncolor{bitsbg}}r>{\columncolor{bldbg}}r>{\columncolor{decbg}}r>{\columncolor{decbg}}r}
\toprule
 & \textbf{\sw{ABC}} & \two{bits}{per CN} & \two{build}{(min)} & \two{CNs}{(min)} & \multicolumn{1}{c|}{\two{CNs +}{primes}}
 & \textbf{\sw{ABC}} & \two{bits}{per CN} & \two{build}{(min)} & \two{CNs}{(min)} & \two{CNs +}{primes} \\
\midrule
""" % grp(facts["count"]))
    rowdefs = [("raw $n$", "000", "001"), ("$\\dmin$", "100", "101"), ("PWT", "010", "011"),
               ("PWT + $\\dmin$", "110", "111")]
    for name, a, b in rowdefs:
        lines.append("%s & %s & %s \\\\\n" % (name, " & ".join(cellv(byt[a])), " & ".join(cellv(byt[b]))))
    lines.append("\\midrule\n")
    lines.append("PWT + $d^{\\ast}$ & \\multicolumn{1}{c}{} & \\multicolumn{1}{c}{} & \\multicolumn{1}{c}{} & "
                 "\\multicolumn{1}{c}{} & \\multicolumn{1}{c|}{} & %s \\\\\n" % " & ".join(cellv(byt["111x"])))
    lines.append("\\bottomrule\n\\end{tabular}}\n\\end{center}\n")
    b100, b101, d = byt["100"], byt["101"], byt["111x"]
    lines.append(r"""{\footnotesize Switch \sw{A} stores $\dmin(n)$ in place of $n$. Switch \sw{B} stores a prime wavelet tree in place of a sorted list. Switch \sw{C} applies every coding trick. With \sw{C}~$=0$, each value or symbol is one VByte. Times are single-threaded minutes on one machine (page~2). Bold marks the best value in each column. Dark blue marks the smallest file.
$^\dagger$The $\dmin$ list itself decodes in %s and %s minutes. The rest is factoring every $d$.
$^\ddagger$The heuristic divisors $d^{\ast}$ replace $\dmin$.
$^\S$Wall-clock time as run. %s. The search alone took %s~s.}

""" % (b100["list_only_min"], b101["list_only_min"], threads_sentence(d["build_threads"]), grp(Decimal(d["build_search_s"]).to_integral_value(ROUND_HALF_UP))))

    # details table
    lines.append(r"""\begin{center}
{\renewcommand{\arraystretch}{1.12}\footnotesize\setlength{\tabcolsep}{3pt}%
\begin{tabular}{@{}llrrrrll@{}}
\toprule
cell & file & bytes & bits/CN & $\times$ text & certify (s) & SHA-256 (prefix) & hosted \\
\midrule
""")
    for t in CELL_ORDER:
        r = byt[t]
        cert = r["certify_s"] + ("\\,(%s thr.)" % r["certify_threads"] if r["certify_threads"] not in ("1", "-") else "")
        lines.append("\\sw{%s} & \\texttt{%s} & %s & %s & %s & %s & \\texttt{%s} & %s \\\\\n" % (
            ("111" + "$^\\ddagger$") if t == "111x" else t, tex(r["file"]), grp(r["bytes"]), r["bits_per_cn"],
            ratio(r, text), cert, r["sha256"][:8], r["hosted"]))
    m = byt["dstar_masks"]
    lines.append("\\midrule\n")
    lines.append("$d^{\\ast}$ masks & \\texttt{%s} & %s & %s & %s & & \\texttt{%s} & %s \\\\\n" % (
        tex(m["file"]), grp(m["bytes"]), m["bits_per_cn"], ratio(m, text), m["sha256"][:8], m["hosted"]))
    for k, name in (("oracle", "oracle"), ("text", "text"), ("gzip", "gzip -9"), ("zstd", "zstd"), ("xz", "xz")):
        r = byt[k]
        f = "\\texttt{%s}" % tex(r["file"]) if r["file"] != "-" else "of the text"
        sh = "\\texttt{%s}" % r["sha256"][:8] if r["sha256"] != "-" else ""
        lines.append("%s & %s & %s & %s & %s & & %s & %s \\\\\n" % (
            name, f, grp(r["bytes"]), r["bits_per_cn"], ratio(r, text), sh,
            {"oracle": r["hosted"], "text": "no"}.get(k, "")))
    lines.append("\\bottomrule\n\\end{tabular}}\n\\end{center}\n")
    lines.append("{\\footnotesize \\texttt{SHA256SUMS} gives the full SHA-256 of each hosted file, and \\texttt{cells/*/CELL} "
                 "gives it for every file. The $d^{\\ast}$ masks are the checkpoint of the search. They are not hosted. "
                 "The authors of the table serve the text.\\\\\n"
                 "The hosted files are at \\url{%s}.}\n" % data_folder(rows))

    # page 2: definitions
    lines.append("\\newpage\n\\sloppy\n")
    o, tx = byt["oracle"], byt["text"]
    lines.append(r"""{\Large\bfseries Definitions and sources}

\textbf{Space.} Space is the file size in bytes $\times 8 / N$, with $N$~=~%(N)s. The VByte list files of cells \sw{000} and \sw{100} include a 24-byte header.

\textbf{Build.} Build is the wall-clock time from the oracle to the closed file. It has two steps. An extraction step turns the oracle into the encoder's input, which is the list of $n$, the list of $\dmin$ or the prime paths. Then the encode step writes the file. Each step ran on one thread on an otherwise idle machine. The time is the median of three runs where three exist. For \sw{A}~$=1$ almost all of it is the search for $\dmin$. On 15 threads that search takes %(s15)s minutes to the list of $\dmin$ and %(p15)s minutes to the $\dmin$ paths. The PWT + $d^{\ast}$ build is quoted as run, with its threads in the footnote, because its divisor search ran once. The file stores the chosen divisors, so it can be rebuilt without repeating the search. That rebuild takes about %(dsr)s minutes from the file's own exported paths (\texttt{make rebuild-111x}).

\textbf{Decode, CNs.} This is a single-thread decode in memory to every CN. It excludes loading the file, checking its payload hash and sieving (%(l0)s--%(l1)s~s). The lists of $n$ decode in sorted order. The trees decode in tree order, and sorting adds %(sort)s minutes. The $\dmin$ lists yield only the divisors $d$. Each CN is $n = d\,(d^{-1} \bmod \lambda(d))$ once $d$ is factored, at %(fd)s\,$\mu$s per number.

\textbf{Decode, CNs + primes.} This is the full content of the text table, every CN with its prime factorization. The trees over full factorizations deliver every prime as they decode. The other files need factoring. Its cost per number was measured on one thread on %(fs)s CNs (every 100th oracle block), and every factorization was checked against the oracle. Factoring $n$ from scratch takes %(fn)s\,$\mu$s (Shallue--Webster Algorithm~1). Factoring the cofactor $r^{\star} = n/d$ takes %(cd)s\,$\mu$s for $\dmin$ and %(cs)s\,$\mu$s for $d^{\ast}$.

\textbf{Certify.} Certify decodes the file, sorts it, checks the footer targets and compares every CN with the oracle, in order. The time includes hashing the oracle file. The trees were certified %(ct)s. Cell \sw{101} was certified %(c101)s. Cells \sw{000}, \sw{001} and \sw{100} were certified %(cl)s. Page~1 gives the thread counts.

\textbf{Verified.} On 2026-10-06 every hosted file was certified against the oracle. So were the rebuilt files of cells \sw{000} and \sw{100}. Cells \sw{010} and \sw{110} were certified on 2026-09-26. On 2026-10-06 the encoders also rewrote cells \sw{000}, \sw{001} and \sw{100} byte for byte from the hash-checked lists of $n$ and $\dmin$. They rewrote the four tree files from the hash-checked path files. They rewrote the $d^{\ast}$ file twice, once from its own exported paths and once from the masks the search saved, which are not hosted. A clean copy of this repository, built from its sources, then verified every file of page~1 and the oracle (\texttt{make verify-CELL}). It rebuilt cells \sw{001} and \sw{101} and the $d^{\ast}$ file, the last from the saved masks (\texttt{make rebuild-CELL}). A second clean copy rebuilt cells \sw{000}, \sw{010}, \sw{100} and \sw{110} from the oracle alone, every intermediate included. It also rebuilt the $d^{\ast}$ file from its own exported paths. Every rebuild matched the published file byte for byte. The prefix self-test (\texttt{make check}) runs every encoder and decoder on the %(pc)s CNs below $10^{12}$ against frozen hashes.

\textbf{Machine.} Every time was measured on an %(mach)s. The compiler is \texttt{%(comp)s}. The tree encoder's model choice and the $d^{\ast}$ search use floating point. The encoders' rebuilds reproduce the published bytes on an x86-64 build with FMA3 (\texttt{NATIVE=1}). The search ran once and has not been repeated. Every decoder is integer-only.

\textbf{Data.} The table of Carmichael numbers below $10^{24}$ is by A.~Shallue and J.~Webster (arXiv:2506.09903). Its text is at \url{%(url)s}. It has %(tb)s bytes and SHA-256\\ \hspace*{1.5em}\texttt{%(ts)s}.\\ The oracle, \texttt{%(of)s}, has %(ob)s bytes and SHA-256\\ \hspace*{1.5em}\texttt{%(os)s}.\\ It holds every $n$ and its prime factors, each proven prime. It decodes to the text byte for byte.

\textbf{Sources.} The build times come from \texttt{results/runs/construction\_*}. The two $\dmin$ times on 15 threads are runs X2O15b (stamp total) and X3 (median of three) in \texttt{results/runs/construction\_round2\_summary.txt} and \texttt{construction\_round1\_summary.txt}. The decode and factoring times come from \texttt{cells/*/runs/time*} and the factoring logs. The certify times come from \texttt{cells/*/runs/}. The rebuilds and certifications of 2026-10-06 are in \texttt{cells/*/runs/rebuild\_*} and \texttt{certify\_*}. The logs of the clean copies of this repository are \texttt{cells/*/runs/repo\_*}, \texttt{results/runs/repo-validation-2026-10-06/} and \texttt{results/runs/review-2026-10-06/}. The bytes and hashes come from the files themselves (\texttt{SHA256SUMS}).

\end{document}
""" % dict(N=grp(facts["count"]), s15=facts["dmin_search_15t_min"], l0=facts["load_s_min"], l1=facts["load_s_max"],
           p15=q(Decimal(byt["111x"]["build_extract_s"]) / 60, 1),
           sort=facts["sort_min"], fd=facts["factor_dmin_us"], fs=grp(facts["factor_sample"]), fn=facts["factor_n_us"],
           cd=facts["cofactor_dmin_us"], cs=facts["cofactor_dstar_us"], ct=tex(when(byt["111"]["certify_date"])),
           c101=tex(when(b101["certify_date"])), cl=tex(when(byt["000"]["certify_date"])), pc=grp(facts["prefix_count"]),
           mach=tex(facts["machine"]), comp=tex(facts["compiler"]), url=tx["url"], tb=grp(tx["bytes"]),
           ts=tx["sha256"], of=tex(o["file"]), ob=grp(o["bytes"]), os=o["sha256"],
           dsr=dstar_rebuild_min(facts)))
    return "".join(lines)


# ------------------------------------------------------------------ main

def outputs():
    rows = read_rows()
    facts, N, text = validate(rows)
    byt = {r["tag"]: r for r in rows}
    out = {}
    for t in CELL_ORDER:
        r = byt[t]
        d = ROOT / "cells" / r["dir"]
        if not d.is_dir():
            raise RenderError("cells/%s missing" % r["dir"])
        out[d / "CELL"] = cell_manifest(r, N, text, byt)
    om, tm = oracle_manifests(byt, N)
    out[ROOT / "oracle" / "ORACLE"] = om
    out[ROOT / "oracle" / "TEXT"] = tm
    out[ROOT / "results" / "INTERMEDIATES"] = intermediates(rows)
    out[ROOT / "SHA256SUMS"] = sha256sums(rows)
    out[ROOT / "results" / "comparison.tex"] = comparison_tex(rows, byt, facts, text, N)
    readme = ROOT / "README.md"
    s = readme.read_text(encoding="utf-8")
    s = splice(s, "table", readme_table(rows, byt, facts, text))
    s = splice(s, "files", readme_files(rows, byt))
    out[readme] = s
    return out


def main():
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("--check", action="store_true", help="report outputs that are out of date; write nothing")
    a = ap.parse_args()
    try:
        out = outputs()
    except (RenderError, KeyError, OSError) as e:
        print("render.py: %s" % e, file=sys.stderr)
        return 2
    stale = 0
    for p, s in out.items():
        cur = p.read_text(encoding="utf-8") if p.exists() else None
        if cur == s:
            continue
        stale += 1
        if a.check:
            print("out of date: %s" % p.relative_to(ROOT))
        else:
            p.write_text(s, encoding="utf-8", newline="\n")
            print("wrote %s" % p.relative_to(ROOT))
    if a.check:
        print("%d of %d outputs out of date" % (stale, len(out)))
        return 1 if stale else 0
    print("%d outputs, %d written" % (len(out), stale))
    return 0


if __name__ == "__main__":
    sys.exit(main())
